const fs = require('fs');
const filePath = 'card-bg-experiment.html';
let content = fs.readFileSync(filePath, 'utf8');

const swordsOld = '<div class="stat-icon-frame"><svg viewBox="0 0 24 24" width="13" height="13"><g filter="url(#statGlow)" fill="none" stroke="url(#statGold)" stroke-width="1.8" stroke-linecap="round"><path d="M4 4l16 16M20 4L4 20"/><path d="M4 4l3 0.5M4 4l0.5 3M20 4l-3 0.5M20 4l-0.5 3M4 20l3-0.5M4 20l0.5-3M20 20l-3-0.5M20 20l-0.5-3" stroke-width="1.3"/></g></svg></div>';
const leafOld = '<div class="stat-icon-frame"><svg viewBox="0 0 24 24" width="13" height="13"><g filter="url(#statGlow)"><path d="M4 20c0-9 6-16 16-16-1 10-8 16-16 16z" fill="none" stroke="url(#statGold)" stroke-width="1.6"/><path d="M6 18c3-6 7-9 12-11" fill="none" stroke="url(#statGold)" stroke-width="1.1" opacity="0.7"/></g></svg></div>';

const swordsNew = '<img src="data:image/png;base64," style="width:34px;height:34px;object-fit:contain;margin:0 auto 3px;display:block;filter:drop-shadow(0 0 4px rgba(201,168,76,0.4));">';
const leafNew = '<img src="data:image/png;base64," style="width:34px;height:34px;object-fit:contain;margin:0 auto 3px;display:block;filter:drop-shadow(0 0 4px rgba(201,168,76,0.4));">';

let count = 0;
if (content.includes(swordsOld)) { content = content.replace(swordsOld, swordsNew); count++; } else { console.error('swords no encontrado'); }
if (content.includes(leafOld)) { content = content.replace(leafOld, leafNew); count++; } else { console.error('leaf no encontrado'); }

// Tambien agrandar los 3 iconos ya insertados (26px -> 34px)
content = content.replace(/width:26px;height:26px;object-fit:contain;margin:0 auto 3px;display:block;filter:drop-shadow\(0 0 4px rgba\(201,168,76,0\.4\)\);/g, 'width:34px;height:34px;object-fit:contain;margin:0 auto 3px;display:block;filter:drop-shadow(0 0 4px rgba(201,168,76,0.4));');

fs.writeFileSync(filePath, content);
console.log(count + ' de 2 iconos restantes reemplazados; todos agrandados a 34px');
